// The alias is absolute because vitest rejects relative ones.
export default {
  test: {
    include: [
      'tests/**/*.test.ts',
    ],
    watchExclude: [
      'tmp/**/*',
    ],
    globals: true,
  },
  resolve: {
    alias: {
      gbnf: '/workspace/ported_implementation/src/index.ts',
    },
  },
};

import { describe, test, expect } from 'vitest';
import GBNF, { RuleType } from 'gbnf';

describe('Iteration', () => {
  test.for([
    ['root ::= "foo"', [{ type: 'char', value: [102] }]],
    [
      'root ::= "foo" | "bar" ',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    [
      'root ::= "foo" | "bar" | "gaz"',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
        { type: 'char', value: [103] },
      ],
    ],
    [
      'root ::= "foo" | "bar" | "baz"',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    ['root ::= [^x]', [{ type: 'char_exclude', value: [120] }]],
    ['root ::= [^f] "o"', [{ type: 'char_exclude', value: [102] }]],
    ['root ::= [^A-Z]', [{ type: 'char_exclude', value: [[65, 90]] }]],
    [
      'root ::= [^A-Z0-9]',
      [
        {
          type: 'char_exclude',
          value: [
            [65, 90],
            [48, 57],
          ],
        },
      ],
    ],
    [
      'root ::= [^A-Z0-9_-]',
      [{ type: 'char_exclude', value: [[65, 90], [48, 57], 95, 45] }],
    ],
    ['\nroot ::= foo\nfoo ::= "foo"\n  ', [{ type: 'char', value: [102] }]],
    [
      '\nroot ::= f\nf ::= foo\nfoo ::= "foo"\n  ',
      [{ type: 'char', value: [102] }],
    ],
    [
      '\nroot ::= foo | "bar"\nfoo ::= "foo"',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    [
      '\nroot ::= foo | bar\nfoo ::= "foo"\nbar ::= "bar"\n  ',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    [
      '\nroot ::= f | b\nf ::= fo\nb ::= ba\nfo ::= foo\nba ::= bar | baz\nfoo ::= "foo"\nbar ::= "bar"\nbaz ::= "baz"\n  ',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    ['root ::= [a-z]', [{ type: 'char', value: [[97, 122]] }]],
    [
      'root ::= [a-zA-Z]',
      [
        {
          type: 'char',
          value: [
            [97, 122],
            [65, 90],
          ],
        },
      ],
    ],
    [
      'root ::= [a-z]?',
      [{ type: 'char', value: [[97, 122]] }, { type: 'end' }],
    ],
    ['root ::= [a-z]+', [{ type: 'char', value: [[97, 122]] }]],
    [
      'root ::= [a-z]*',
      [{ type: 'char', value: [[97, 122]] }, { type: 'end' }],
    ],
    ['\n  root ::= "foo"\n  foo ::= "foo"', [{ type: 'char', value: [102] }]],
    [
      '\n  root  ::= (expr "=" term "\\n")+\n  expr  ::= term ([-+*/] term)*\n  term  ::= [0-9]+\n  ',
      [{ type: 'char', value: [[48, 57]] }],
    ],
  ] as [string, { type: string; value: number[] }[]][])(
    'It returns parse state for a grammar (%#): `%s`',
    ([grammar, expected]) => {
      let state = GBNF(grammar);
      expect([...state]).toEqual(expected);
    }
  );
});

import { describe, test, expect } from 'vitest';
import GBNF, { GrammarParseError } from 'gbnf';

describe('Validate Grammar', () => {
  test.for([
    'root ::= "foo"',
    'root ::= "foo" | "bar"',
    'root ::= ("foo" | "bar")',
    'root ::= ("foo" | "bar")?',
    'root ::= ("foo" | "bar")*',
    'root ::= ("foo" | "bar")+',
    'root ::= [a-z]',
    'root ::= [a-zA-Z]',
    'root ::= [a-zA-Z0-9]',
    'root ::= [a-zA-Z0-9]*',
    'root ::= [a-zA-Z0-9]?',
    'root ::= [a-z]+',
    'root ::= [a-zA-Z0-9]+',
    'root ::= ([a-zA-Z0-9])*',
    'root ::= ([a-zA-Z0-9])?',
    'root ::= ([a-zA-Z0-9])+',
    '\n  root ::= foo\n  foo ::= "foo"',
    '\n  root ::= foo\n  foo ::= "foo" | "bar" | ([a-z])?\n  ',
  ])('It parses a grammar (%#): `%s`', (grammar) => {
    expect(GBNF(grammar)).toBeTruthy();
  });

  test.for([
    ['', 0, 'No rules were found'],
    ['root = "foo"', 5, 'Expecting ::= at 5'],
    ['root ::= foo\nfoo := "foo"\n  ', 17, 'Expecting ::= at 17'],
    ['root ::= foo', 9, 'Undefined rule identifier "foo"'],
    ['root ::= foo\nbar ::= "bar"\n  ', 9, 'Undefined rule identifier "foo"'],
    [
      'root ::= foo\nfoo ::= baz\nbar ::= "bar"\n  ',
      21,
      'Undefined rule identifier "baz"',
    ],
    ['root ::= foo ::= bar', 13, 'Expecting newline or end at 13'],
    ['root ::= ([a-z]\nfoo ::= "foo"\n  ', 20, "Expecting ')' at 20"],
  ] as [string, number, string][])(
    'It reports an error for an invalid grammar (%#): `%s`',
    ([grammar, errorPos, errorReason]) => {
      expect(() => {
        GBNF(grammar);
      }).toThrowError(new GrammarParseError(grammar, errorPos, errorReason));
    }
  );
});

