import { describe, test, expect } from 'vitest';
import GBNF, { GBNF as named, ParseState, RuleType, isRange, GrammarParseError, InputParseError } from 'gbnf';

describe('public api', () => {
  test('README walkthrough', () => {
    let state = GBNF('root  ::= "I like green eggs and ham"');
    expect([...state]).toEqual([{ type: 'char', value: [73] }]);
    state = state.add('I li');
    expect([...state]).toEqual([{ type: 'char', value: [107] }]);
    state = state.add('ke gree');
    expect([...state]).toEqual([{ type: 'char', value: [110] }]);
  });

  test('surface', () => {
    const state = GBNF('root ::= "yes" | "no"');
    expect(named).toBe(GBNF);
    expect(state).toBeInstanceOf(ParseState);
    expect(state.grammar).toBe('root ::= "yes" | "no"');
    expect(state.size).toBe(2);
    expect([...state.rules()]).toHaveLength(2);
    expect(RuleType.CHAR).toBe('char');
    expect(isRange([65, 90])).toBe(true);
    expect(isRange(65)).toBe(false);
  });

  test('code point + array input', () => {
    expect([...GBNF('root ::= "foo"', [102, 111])]).toEqual([{ type: 'char', value: [111] }]);
    expect([...GBNF('root ::= "foo"', 102)]).toEqual([{ type: 'char', value: [111] }]);
  });

  test('errors', () => {
    expect(() => GBNF('')).toThrow(GrammarParseError);
    expect(() => GBNF('root ::= "foo"', 'z')).toThrow(InputParseError);
    try { GBNF('root ::= "foo"', 'z'); } catch (e) {
      expect((e as InputParseError).src).toBe('z');
      expect((e as InputParseError).name).toBe('InputParseError');
    }
    try { GBNF('root = "foo"'); } catch (e) {
      expect((e as GrammarParseError).pos).toBe(5);
      expect((e as GrammarParseError).reason).toBe('Expecting ::= at 5');
      expect((e as GrammarParseError).grammar).toBe('root = "foo"');
    }
  });
});
